void Solver::bump_var(int var, double coeff) {
    double inc = var_inc * coeff;
    // Apply a non-linear boost: variables at higher decision levels get extra bump
    // to help escape local optima by emphasizing recently conflicting variables
    int lv = level[var];
    if (lv > 0) {
        // Scale boost by log of level to favor deeper variables without overflow risk
        double level_boost = 1.0 + 0.1 * (lv > 10 ? 10.0 : (double)lv);
        inc *= level_boost;
    }
    if ((activity[var] += inc) > 1e100) {
        for (int i = 1; i <= vars; i++) activity[i] *= 1e-100;
        var_inc *= 1e-100;
    }
    if (vsids.inHeap(var)) vsids.update(var);
}
